describe('Form Submission with Past-Date Field', () => {
    beforeEach(() => {
        cy.visit('/form-page'); // Replace with the actual URL of the form page
    });

    it('should display an error when a future date is submitted in the past-date field', () => {
        const futureDate = new Date();
        futureDate.setDate(futureDate.getDate() + 1); // Set to tomorrow's date

        cy.get('input[name="past-date"]').type(futureDate.toISOString().split('T')[0]); // Input future date
        cy.get('form').submit(); // Submit the form

        cy.get('.error-message') // Replace with the actual selector for the error message
            .should('be.visible')
            .and('contain', 'Please enter a valid past date.'); // Replace with the actual error message
    });

    it('should not display an error when a valid past date is submitted', () => {
        const pastDate = new Date();
        pastDate.setDate(pastDate.getDate() - 1); // Set to yesterday's date

        cy.get('input[name="past-date"]').type(pastDate.toISOString().split('T')[0]); // Input past date
        cy.get('form').submit(); // Submit the form

        cy.get('.error-message') // Replace with the actual selector for the error message
            .should('not.exist'); // Ensure no error message is displayed
    });
});
